            if tail=='pins': return self.out({'pins':[{'message':msgobj(q('SELECT * FROM messages WHERE id=?',(x['message_id'],),True)),'pinned_by':x['pinned_by'],'pinned_at':x['pinned_at']} for x in q('SELECT * FROM pins WHERE message_id IN (SELECT id FROM messages WHERE channel_id=?) ORDER BY message_id DESC',(cid,))],'next_cursor':None})
            if tail=='read':
                r=q('SELECT * FROM reads WHERE user_id=? AND channel_id=?',(u['id'],cid),True); last=r['last_event_id'] if r else 0
                return self.out({'read_state':{'channel_id':cid,'last_read_event_id':last,'unread_count':0,'mention_count':0}})
            return self.out({'channel':chan(c)})
